"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["46999"],{9349(a){a.exports=JSON.parse('{"id":"FIN-999","slug":"data-visualization","term":"Data Visualization","also_known_as":[],"difficulty":"Intermediate","definition":"Data visualization is the presentation of data in graphical form, such as charts, graphs and maps, to make information easier to understand, analyse and communicate.","explanation":["Large amounts of numbers can be difficult to interpret. Visualizations help people see patterns, trends, comparisons and outliers that might be hidden in tables of figures.","Different types of visualization suit different purposes. Line charts show changes over time, such as a share price or GDP growth. Bar charts compare quantities across categories, such as sales by region. Pie charts show parts of a whole, although they can be hard to read with many slices. Scatter plots show relationships between two variables. Heat maps use colour to show values across a grid.","For example, a line chart showing a company\'s revenue and profit over ten years can quickly reveal whether profit margins have improved or declined, which would take much longer to see from a table.","Good data visualization is clear, accurate and honest. Poor or misleading visualizations can distort understanding, for example by starting a chart\'s vertical axis well above zero to exaggerate small changes, using inconsistent scales, or cluttering charts with unnecessary detail. In finance, visualizations are widely used in reports, presentations, dashboards and investment research."],"note":"","total":1725,"prev":{"slug":"data-table","term":"Data Table"},"next":{"slug":"day-count-convention","term":"Day-Count Convention"}}')}}]);